def solve(a, b):
    while b != 0:
        t = b
        b = a % b
        a = t
    return a

def solve(n):
    s = 0
    while n != 0:
        s = s + n % 10
        n = n // 10
    return s

def solve(x, lo, hi):
    if x < lo:
        return lo
    if x > hi:
        return hi
    return x

def solve(n):
    steps = 0
    while n != 1:
        if n % 2 == 0:
            n = n // 2
        else:
            n = 3 * n + 1
        steps = steps + 1
    return steps
